package com.wendev.kolas.ui.result

import android.graphics.Bitmap
import com.wendev.kolas.data.detection.Detection

/** State of the pushed detection-result screen. */
sealed interface ResultUiState {

    /** The detection is being read from storage. Transient and real. */
    data object Loading : ResultUiState

    /** The reading, its photo and its per-class breakdown are ready to render. */
    data class Ready(
        val detection: Detection,
        val bitmap: Bitmap
    ) : ResultUiState

    /**
     * Explanation is generated by the LLM in Slice 3. Kept in the sealed type so
     * the branch is explicit, but Slice 2 never defaults to it.
     */
    data object LoadingExplanation : ResultUiState

    /** Ditto — reserved for the Slice 3 explanation failure path. */
    data class ExplanationFailed(val message: String) : ResultUiState

    /** The detection id could not be resolved (e.g. lost on process death). */
    data class Error(val message: String) : ResultUiState
}
